function pausar() {
  if (estado !== 'jugando') return;
  estado = 'pausa';
  teclas.ArrowLeft = teclas.ArrowRight = false;
  botonDir = 0; dedo = null;
  $('pausado').hidden = false;
  $('pausa').setAttribute('aria-pressed', 'true');
  $('seguir').focus();
  anunciar('En pausa');
}
